<?php get_header(); while(have_posts()): the_post();
$login=c91_get_streamer_login(); $all=c91_get_twitch_context([$login]); $ctx=$all[$login]??null; $user=$ctx['user']??null; $stream=$ctx['stream']??null; $live=!empty($ctx['is_live']); $url=$ctx['url']??'https://www.twitch.tv/'.$login;
?>
<section class="page-hero"><div class="shell streamer-single-head"><div><?php if(!empty($user['profile_image_url'])): ?><img class="avatar-large" src="<?php echo esc_url($user['profile_image_url']); ?>" alt=""><?php else: ?><div class="avatar-large placeholder"><?php echo esc_html(mb_substr(get_the_title(),0,1)); ?></div><?php endif; ?></div><div><span class="eyebrow"><?php echo $live?'● JETZT LIVE':'STREAMER'; ?></span><h1><?php echo esc_html($user['display_name']??get_the_title()); ?></h1><p><?php echo esc_html($live ? (($stream['game_name']?:'Live').' · '.number_format_i18n((int)($stream['viewer_count']??0)).' Zuschauer') : ($user['description']??get_the_excerpt())); ?></p><div class="social-row"><a class="btn primary" target="_blank" rel="noopener" href="<?php echo esc_url($url); ?>"><?php echo $live?'Stream ansehen':'Twitch öffnen'; ?></a></div></div></div></section>
<?php if($live): ?><section class="section"><div class="shell"><div class="single-twitch-player"><iframe src="<?php echo esc_url(c91_twitch_player_url($login)); ?>" allowfullscreen loading="lazy" title="Twitch Stream"></iframe></div></div></section><?php endif; ?>
<?php if(trim(get_the_content())): ?><section class="section"><div class="shell content-card prose"><?php the_content(); ?></div></section><?php endif; ?>
<?php endwhile; get_footer(); ?>
